"""Store inventory cache."""


class InventoryCache:
    def __init__(self):
        self._data = {}

    def _key(self, store_id):
        return "store:" + store_id[:3]

    def put(self, store_id, stock):
        self._data[self._key(store_id)] = stock

    def take(self, store_id, default=None):
        return self._data.get(self._key(store_id), default)

